"""Seating charts: students in rows, sorted by last name."""

from operator import attrgetter
from typing import List

from rosterkit.models import Student


def seating_rows(
    students: List[Student], per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    if per_row <= 0 or not students:
        raise ValueError("need students and seats per row")
    ordered = sorted(students, key=attrgetter("last_name"))
    return row_lines(ordered, per_row)

def row_lines(
    ordered: List[Student], per_row: int
) -> List[str]:
    starts = range(0, len(ordered), per_row)
    rows = [ordered[seat:seat + per_row] for seat in starts]
    return [row_text(*pair) for pair in enumerate(rows, 1)]

def row_text(number: int, group: List[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

