# owner: platform
"""Tests for the seating chart helper."""

import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make_student(
    last_name: str, first_name: str
) -> Student:
    return Student("0", last_name, first_name, "A")

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Quillon", "Ada"),
            make_student("Thistle", "Bram"),
            make_student("Ardent", "Cy"),
        ]

    def test_sorted_by_last_name_then_chunked(self):
        self.assertEqual(
            seating_rows(self.roster, 2),
            [
                "Row 1: Ardent, Cy | Dunmere, Piet",
                "Row 2: Halloway, Juno | Quillon, Ada",
                "Row 3: Thistle, Bram"
            ]
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
